import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# --------------------------------------------------------------------
# CUDA source (kernel + wrapper)
# --------------------------------------------------------------------
cuda_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

template <typename scalar_t>
__global__ void matmul_fp16_kernel(const __half* __restrict__ A,
                                   const __half* __restrict__ B,
                                   __half* __restrict__ C,
                                   int M, int N, int K) {
    // 2D thread block mapping to output matrix C (MxN)
    int row = blockIdx.y * blockDim.y + threadIdx.y;  // M dimension
    int col = blockIdx.x * blockDim.x + threadIdx.x;  // N dimension

    if (row < M && col < N) {
        float acc = 0.0f;
        // stride‑based dot product over K
        for (int k = 0; k < K; ++k) {
            // load half values, convert to float for accumulation
            __half a = A[row * K + k];
            __half b = B[k * N + col];
            acc += __half2float(a) * __half2float(b);
        }
        // write result back as half
        C[row * N + col] = __float2half(acc);
    }
}

// C++ wrapper
torch::Tensor matmul_fp16(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "inputs must be CUDA tensors");
    TORCH_CHECK(A.dtype() == torch::kHalf && B.dtype() == torch::kHalf,
                "inputs must be torch.float16");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "inputs must be 2‑D matrices");
    int64_t M = A.size(0);
    int64_t K = A.size(1);
    int64_t Kb = B.size(0);
    int64_t N = B.size(1);
    TORCH_CHECK(K == Kb, "inner dimensions must match");

    auto C = torch::empty({M, N}, A.options());

    const dim3 block(16, 16);
    const dim3 grid((N + block.x - 1) / block.x,
                    (M + block.y - 1) / block.y);

    // launch kernel
    AT_DISPATCH_FLOATING_TYPES_AND_HALF(
        A.scalar_type(), "matmul_fp16_kernel", ([&] {
            matmul_fp16_kernel<<<grid, block>>>(
                reinterpret_cast<const __half*>(A.data_ptr<scalar_t>()),
                reinterpret_cast<const __half*>(B.data_ptr<scalar_t>()),
                reinterpret_cast<__half*>(C.data_ptr<scalar_t>()),
                static_cast<int>(M),
                static_cast<int>(N),
                static_cast<int>(K));
        })
    );

    // synchronize to surface errors early
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        printf("CUDA kernel launch error: %s\\n", cudaGetErrorString(err));
    }

    return C;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("matmul_fp16", &matmul_fp16, "Half‑precision matrix multiply (CUDA)");
}
'''

# --------------------------------------------------------------------
# Compile the extension in‑line
# --------------------------------------------------------------------
_ext = load_inline(name='matmul_fp16_ext',
                   cpp_sources='',
                   cuda_sources=cuda_source,
                   functions=['matmul_fp16'],
                   verbose=False)

# --------------------------------------------------------------------
# PyTorch model that uses the custom kernel
# --------------------------------------------------------------------
class ModelNew(nn.Module):
    """
    Drop‑in replacement for the reference Model.
    Performs C = A @ B using a custom half‑precision CUDA kernel.
    """
    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        # Ensure tensors are on CUDA and dtype is float16
        if not A.is_cuda:
            A = A.cuda()
        if not B.is_cuda:
            B = B.cuda()
        A = A.to(torch.float16)
        B = B.to(torch.float16)
        return _ext.matmul_fp16(A, B)

# --------------------------------------------------------------------
# Helper functions matching the reference script
# --------------------------------------------------------------------
def get_inputs():
    M = 256
    N = 256
    K = 131072 * 4
    A = torch.rand(M, K, dtype=torch.float16, device='cuda')
    B = torch.rand(K, N, dtype=torch.float16, device='cuda')
    return [A, B]

def get_init_inputs():
    return []   # No special initialization required

# --------------------------------------------------------------------
# Example sanity check (can be removed in production)
# --------------------------------------------------------------------
if __name__ == "__main__":
    A, B = get_inputs()
    model = ModelNew().cuda()
    C = model(A, B)
    # compare with torch.matmul for verification (optional)
    C_ref = torch.matmul(A, B)
    max_err = (C.float() - C_ref).abs().max()
    print(f"max absolute error vs torch.matmul: {max_err.item()}")
